<template><section class="module-page learning-analysis"><header class="module-heading"><div><h1>学情分析</h1><p>查看平台用户学习进度、完成情况和教师评价。</p></div><el-button icon="el-icon-refresh" @click="load">刷新</el-button></header><section class="metrics"><div><i class="el-icon-user"/><strong>{{overview.totalUsers||0}}</strong><span>平台用户</span></div><div><i class="el-icon-time"/><strong>{{overview.activeUsers||0}}</strong><span>学习中</span></div><div><i class="el-icon-success"/><strong>{{overview.completedResources||0}}</strong><span>已完成资源</span></div><div><i class="el-icon-data-analysis"/><strong>{{Number(overview.averageProgress||0).toFixed(1)}}%</strong><span>平均进度</span></div></section><div class="analysis-layout"><section class="module-table-wrap"><el-table :data="overview.users||[]"><el-table-column prop="userName" label="用户"/><el-table-column prop="resourcesStarted" label="已学习资源"/><el-table-column label="平均进度"><template slot-scope="s"><el-progress :percentage="Math.round(Number(s.row.averageProgress||0))"/></template></el-table-column><el-table-column prop="completedResources" label="完成资源"/><el-table-column label="评价" width="110"><template slot-scope="s"><el-button type="text" @click="openEvaluation(s.row)">写评价</el-button></template></el-table-column></el-table></section><aside class="evaluation-panel"><h2>教师评价</h2><p>选择用户后填写学习反馈。</p><el-form v-if="selected"><el-form-item label="用户">{{selected.userName}}</el-form-item><el-form-item label="评分"><el-rate v-model="evaluation.rating"/></el-form-item><el-form-item label="评价"><el-input v-model="evaluation.content" type="textarea" :rows="5" placeholder="填写学习表现、建议和改进方向"/></el-form-item><el-button type="primary" :loading="saving" @click="saveEvaluation">保存评价</el-button></el-form><el-empty v-else description="请选择用户"/></aside></div></section></template>
<script>import {getLearningOverview,createEvaluation} from '@/api/LearningAnalysis';export default{data:()=>({overview:{users:[]},selected:null,evaluation:{rating:5,content:''},saving:false}),created(){this.load()},methods:{async load(){const r=await getLearningOverview();this.overview=r.data||{users:[]}},openEvaluation(row){this.selected=row;this.evaluation={rating:5,content:''}},async saveEvaluation(){if(!this.evaluation.content.trim())return this.$message.warning('评价内容不能为空');this.saving=true;try{await createEvaluation(this.selected.userId,this.evaluation);this.$message.success('评价已保存');this.selected=null;await this.load()}finally{this.saving=false}}}}</script>
<style scoped>.learning-analysis{width:100%}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.metrics>div{padding:18px;background:#fff;border:1px solid var(--ui-border);border-radius:8px}.metrics i{display:block;color:var(--ui-primary);font-size:22px}.metrics strong{display:block;margin:8px 0 4px;font-size:27px}.metrics span{color:var(--ui-muted);font-size:12px}.analysis-layout{display:grid;grid-template-columns:1fr 330px;gap:18px}.evaluation-panel{padding:18px;background:#fff;border:1px solid var(--ui-border);border-radius:8px}.evaluation-panel h2{margin:0}.evaluation-panel p{color:var(--ui-muted);font-size:12px}@media(max-width:900px){.analysis-layout{grid-template-columns:1fr}}@media(max-width:600px){.metrics{grid-template-columns:repeat(2,1fr)}}</style>
